        home_long_title: "Niyə Ovlink seçməlisiniz?",
        why_value_title: "Ovlink hansı dəyəri yaradır?",
        why_features_title: "Əsas imkanlar",
        why_for_whom_title: "Kimlər üçündür və kimlər üçün deyil?",
        why_how_title: "Qısa iş prinsipi və təhlükəsizlik",

        home_long_p1: "Ovlink link paylaşımını daha aydın və etibarlı etmək üçün yaradılıb. Uzun URL-ləri qısa, oxunaqlı və idarə edilə bilən formata çevirərək paylaşımı sadələşdirir və komandalara vahid iş axını verir.",
        home_long_p2: "Xidmət xüsusi alias, şifrəli link, bitmə tarixi, klik limiti, aktiv custom domen seçimi, QR yaradılması və əsas statistika kimi mövcud funksiyaları bir yerdə təqdim edir. Məqsəd funksionallığı artırarkən idarəetməni sadə saxlamaqdır.",
        home_long_p3: "Ovlink yaradıcılar, freelancerlər, kiçik komandalar və bizneslər üçün uyğundur. Platforma phishing, zərərli proqram yayımı, fırıldaqçılıq, saxta yönləndirmə və qanunsuz məzmun üçün nəzərdə tutulmayıb; belə hallarda icra tədbirləri tətbiq oluna bilər.",
        home_long_p4: "İstifadəçi qısa linki açdıqda sistem əvvəlcə qayda və təhlükəsizlik yoxlamalarını tətbiq edir, sonra şərtlər uyğundursa yönləndirir. Şübhəli linklər report axını ilə yoxlanıla bilər və lazım olduqda məhdudlaşdırıla və ya deaktiv edilə bilər.",
        home_why_teaser_p1: "Ovlink etibarlı və idarəolunan qısa linklər istəyənlər üçün hazırlanıb. Platforma legitim paylaşım üçün nəzərdə tutulub və təhlükəsizlik/siyasət qaydalarını pozan linkləri məhdudlaşdıra bilər.",
        home_why_teaser_p2: "Paylaşma sadə qalır, amma necə işlədiyini gizlətmirik. Təhlükəsizlik, moderasiya və məlumatların işlənməsi barədə tam izah üçün davamını oxuyun.",
        home_why_cta: "Ovlink haqqında ətraflı oxu",
        home_value_title: "Necə işləyir və niyə təhlükəsizdir",
        home_mini_feature_1_title: "Ani Qısaltma",
        home_mini_feature_1_text: "URL daxil edin və dərhal qısa link alın. İstəyə görə xüsusi alias və link şifrəsi əlavə edə bilərsiniz.",
        home_mini_feature_2_title: "Praktik Analitika",
        home_mini_feature_2_text: "Statistikada klik, brauzer, əməliyyat sistemi və ölkə göstəriciləri görünür. Bu göstəricilər yalnız yönləndirmə davam etdikdə qeydə alınır.",
        home_mini_feature_3_title: "Təhlükəsizlik Nəzarəti",
        home_mini_feature_3_text: "Report sistemi, bloklanmış domen yoxlaması və admin moderasiyası riskli linkləri məhdudlaşdırmağa kömək edir.",
        home_mini_feature_4_title: "Rahat İdarəetmə",
        home_mini_feature_4_text: "Mobil uyğun interfeys, sürətli form və dashboard ilə linklərinizi asan şəkildə idarə edə bilərsiniz.",
        home_value_p1: "Uzun linki daxil edin, sistem qısa kod yaradır və hədəfi yadda saxlayır. İstəyə görə xüsusi ad, parol, bitmə tarixi və klik limiti seçə bilərsiniz. Ziyarətçi linki açanda qaydalar yoxlanır; hamısı uyğundursa dərhal yönləndirmə edilir. Bu yanaşma sürəti qoruyur, sizə isə nəzarət verir.",
        home_value_p2: "Analitika üçün yalnız lazım olan məlumatları saxlayırıq: klik vaxtı, cihaz/brauzer tipi və təxmini ölkə kodu. İctimai analitika üçün tam IP ünvanı saxlamırıq və məlumatları satmırıq. Bu yığcam statistika performansı izləməyə kömək edir, məxfiliyi isə qoruyur.",
        home_value_p3: "Təhlükəsizlik iş axınının bir hissəsidir. Şikayətlər riskli linkləri işarələməyə imkan verir, moderasiya isə qaydaları pozan ünvanları deaktiv edə bilər. Limitlər və domen blokları sui-istifadəni azaldır, aydın qaydalar isə gözləntiləri şəffaf edir. Buna görə Ovlink sadə görünür, amma arxada güclü nəzarət var.",
        home_value_p4: "Şəffaflıq bizim əsas qaydamızdır. Linklərin necə yaradıldığını, necə yönləndiyini və məlumatların necə işlənildiyini açıq şəkildə izah edirik. Bu yanaşma həm istifadəçilər, həm də reklam platformaları üçün etibarlı mühit yaradır.",
        home_value_p5: "İstifadəçi təcrübəsi də vacibdir: mobil uyğun dizayn, sürətli yükləmə və sadə addımlar link qısaltmanı rahat edir. Yardım və əlaqə bölmələri sualları tez cavablandırmaq üçün hazırdır. Bu balans Ovlink-i həm gündəlik istifadə, həm də peşəkar layihələr üçün uyğun edir. Aydın qaydalar və moderasiya istifadəçi etibarını gücləndirir.",
        home_value_p6: "İnformasiya keyfiyyəti də vacibdir: səhifələrdə nə etdiyimizi aydın göstərir, istifadə qaydalarını sadə dildə izah edirik. Bu, həm axtarış sistemləri, həm də reklam platformaları üçün etibarlı siqnaldır. Nəticədə platforma uzunmüddətli və təhlükəsiz istifadə üçün uyğun olur.",
        why_ovlink_link: "Niyə Ovlink?",
