        updates_release_20260916_authgate_title: "Monolith Şifrə Sıfırlama və Keçid Qapısı Redizaynı",
        updates_release_20260916_authgate_badge: "16.09.2026",
        updates_release_20260916_authgate_desc: "Şifrə sıfırlama (reset-password) və qorunan link keçid (proceed) səhifələri Monolith dizayn sisteminə uyğun olaraq sıfırdan yeniləndi.",
        updates_release_20260916_authgate_item1: "Qaranlıq Monoxrom Estetika: Pitch-black kətan, hairline sərhədlər, Inter tipoqrafiyası və dinamik kursor effektləri.",
        updates_release_20260916_authgate_item2: "Təkmilləşdirilmiş Təhlükəsizlik və UI: Tam responsive Monolith formaları, axıcı fokus halqaları və toxunma ekranlarına uyğunlaşdırılmış hərəkət fiziki.",
        updates_release_20260916_authgate_item3: "Təmiz Monolith Arxitekturası: Köhnə Bootstrap asılılıqları aradan qaldırıldı, qüsursuz i18n və CSRF inteqrasiyası qorundu.",
        updates_release_20260916_resp_title: "Monolith Mobil və Planşet Responsivliyi",
        updates_release_20260916_resp_badge: "16.09.2026",
        updates_release_20260916_resp_desc: "Ana səhifə bütün mobil (320px-ə qədər), planşet və böyük ekranlarda Monolith minimalist dizayn sisteminə tam uyğunlaşdırıldı.",
        updates_release_20260916_resp_item1: "Axıcı Tipoqrafiya və Kompozitor: Dar ekranlarda daşmayan başlıqlar, iOS avto-zoom qoruması və rahat toxunma hədəfləri.",
        updates_release_20260916_resp_item2: "Planşet & Mobil Bento Qridi: İki sütunlu planşet balansı, təmiz 1 sütunlu mobil axın və adaptiv analitika/iş sahəsi vizualları.",
        updates_release_20260916_resp_item3: "Təkmil Mobil Naviqasiya & Kursor İdarəsi: iOS safe-area dəstəyi və toxunma ekranlarında təbii sistem kursorunun qorunması.",
        updates_release_20260916_qr_title: "Monolith QR Kod Özəlləşdirilməsi & Rəng Seçicisi",
        updates_release_20260916_qr_badge: "16.09.2026",
        updates_release_20260916_qr_desc: "Ana səhifədəki QR kod generatoru Monolith dizayn sisteminə tam uyğunlaşdırıldı: xüsusi tünd palitra, mövzu cütləri və dəqiq rəng nəzarəti əlavə edildi.",
        updates_release_20260916_qr_item1: "Xüsusi Rəng Seçicisi: Brauzerin standart göyqurşağı qutusu əvəzinə Monolith tünd palitrası və canlı hex giriş sahəsi.",
        updates_release_20260916_qr_item2: "Hazır Mövzu Cütləri: Classic (Qara/Ağ), Monolith Dark (Ağ/Dərin Qara) və Slate bir toxunuşla tətbiq edilir.",
        updates_release_20260916_qr_item3: "Pipet & Hekskod Dəstəyi: Ekranda rəng seçmək üçün EyeDropper dəstəyi və cəld rəng çipləri.",
        home_redesign_20260913_title: "Ana Səhifə Yeniləndi: “Sakit Dəqiqlik” Dizaynı",
        home_redesign_20260913_badge: "13.09.2026",
        home_redesign_20260913_desc: "Ana səhifə tamamilə sıfırdan, premium-minimalist dizayn dili ilə yenidən quruldu: təmiz kanvas ritmi, frosted naviqasiya, bir aksent rəng və daha aydın iyerarxiya.",
        home_redesign_20260913_item1: "Yeni Komposer: link yaratmaq üçün tək, diqqət mərkəzində olan giriş sahəsi; ətraflı tənzimləmələr sakit açılışla açılır.",
        home_redesign_20260913_item2: "Yeni Bölmə Strukturu: xüsusiyyətlər, iş axını və alətlər üçün full-bleed plitələr — səth rəngi dəyişərək bölməni ayırır.",
        home_redesign_20260913_item3: "Dizayn Sistemi: SF üslublu sistem şrifti, 600 çəkili başlıqlar, mənfi letter-spacing, hairline sərhədlər və avtomatik tünd rejim.",
