        updates_release_20260917_del_title: "Monolith Dashboard & Təhlükəsiz Silmə Təkmilləşdirməsi",
        updates_release_20260917_del_badge: "17.09.2026",
        updates_release_20260917_del_desc: "İdarə panelində mərkəzləşdirilmiş 3 saniyəlik təhlükəsizlik taymerli silmə modalı tətbiq edildi, axtarış və çeşidləmə filtrləri bərpa edildi, qovluq və teqlərin vizual kontrastı Monolith standartlarına uyğunlaşdırıldı.",
        updates_release_20260917_del_item1: "Mərkəzi Təhlükəsiz Silmə Modalı: Fərdi və toplu silmə əməliyyatlarında 3 saniyəlik kilidləmə taymeri və xarici klik bloklaması olan Monolith xəbərdarlıq pəncərəsi inteqrasiya edildi.",
        updates_release_20260917_del_item2: "Filtr və Axtarış Sistemi: İdarə panelində link axtarışı, vəziyyət filtrləri və çeşidləmə seçimlərinin icra mexanizmi düzəldildi və səhifələmə yenilənməsi təmin edildi.",
        updates_release_20260917_del_item3: "Görünən Qovluq və Teqlər: Cədvəldə qaranlıq görünən qovluq və teq adları yüksək kontrastlı Monolith kapsul dizaynına keçirildi, Enter ilə yadda saxlama və təklif seçimləri aktivləşdirildi.",
        updates_release_20260917_del_item4: "Toplu İdxal və Naviqasiya: Toplu link idxal pəncərəsində mətn sahəsinin sıxılması aradan qaldırıldı, naviqasiya zolağının arxa plan şəffaflığı aradan qaldırılaraq üst-üstə düşmə problemi həll edildi.",
        updates_release_20260918_analytics_title: "Enterprise Monolith Analitika Yenilənməsi",
        updates_release_20260918_analytics_badge: "18.09.2026",
        updates_release_20260918_analytics_desc: "Statistika səhifəsi sıxıcı və qaranlıq qrafiklərdən təmizlənərək Linear və Vercel standartlarında geniş, sakit və lüks Enterprise idarəetmə mərkəzinə çevrildi.",
        updates_release_20260918_analytics_item1: "Geniş Lüks Dizayn: Gözü yoran parıltılı dairələr və sıx elementlər ləğv edildi, geniş nəfəslik sahəsinə (negative space) malik müasir interfeys quruldu.",
        updates_release_20260918_analytics_item2: "3 Əsas KPI Kartı: Ümumi kliklər, unikal ziyarətçilər və əsas coğrafi məkan zərif rəqəmlər və sakit göstəricilərlə təqdim edildi.",
        updates_release_20260918_analytics_item3: "Hamar Zaman Qrafiki: İncə xətt və sakit tünd qradiyent sahəyə (spline area) malik yeni Chart.js zaman qrafiki tətbiq edildi.",
        updates_release_20260918_analytics_item4: "Dinamik Vaxt Filtrləri & Siyahılar: 7 Gün, 30 Gün və Bütün Vaxt filtrləri, ölkələr və texnologiyalar üçün incə zolaqlı reytinq panelləri əlavə edildi.",
        updates_release_20260918_tags_title: "Dashboard Teqlər və Qovluq Sistemi Təkmilləşdirməsi",
        updates_release_20260918_tags_badge: "18.09.2026",
        updates_release_20260918_tags_desc: "İdarə panelində linklərə teq və qovluq əlavə edilməsi bərpa edildi, birbaşa redaktə modalından və cəld yaratmadan teq təyini təmin edildi.",
        updates_release_20260918_tags_item1: "Teq Saxlanılması & Normalizasiyası: Serverdə teqlərin massiv kimi saxlanılması təmin edildi və cədvəldə itmə problemi tam aradan qaldırıldı.",
        updates_release_20260918_tags_item2: "Redaktə Modalı ilə İnteqrasiya: Link redaktə pəncərəsində hədəf URL ilə yanaşı qovluq və teqlərin dəyişdirilməsi imkanı yaradıldı.",
        updates_release_20260918_tags_item3: "Cəld Link Yaratmada Teqlər: İdarə panelinin cəld qısaltma bölməsində birbaşa teq daxil edilməsi aktivləşdirildi.",
        updates_release_20260918_tags_item4: "Davamlı Teq Təhlili: Keçmiş və yeni teqlərin JSON, vergüllə ayrılmış və ya massiv formatlarında xətasız oxunması təmin edildi.",
        updates_release_20260918d_security_title: "Təhlükəsizlik və Plan Sərhədləri Yenilənməsi",
        updates_release_20260918d_security_badge: "18.09.2026",
        updates_release_20260918d_security_desc: "Link yönləndirmə qoruyucuları birləşdirildi, gündəlik limitlər bütün yaratma yollarında tətbiq edildi və sessiya ləğvi artıq bütün cihazlarda qüvvədədir.",
        updates_release_20260918d_security_item1: "Yönləndirmə Qoruyucuları: Deaktiv edilmiş, vaxtı bitmiş, bloklanmış və ya təhlükəli linklər — şifrəli link axını daxil olmaqla — heç bir ünvan vasitəsilə açıla bilməz.",
        updates_release_20260918d_security_item2: "Gündəlik Limitlər: Free hesablar üçün gündə 50 link (bir dəfəyə 5), Pro üçün 500 link (bir dəfəyə 50) limiti indi həm tək link, həm də toplu idxal yolunda eyni qaydada yoxlanılır.",
        updates_release_20260918d_security_item3: "Xüsusi Domenlər: Yeni domen əlavə etmək Pro planı tələb edir; artıq təsdiqlənmiş domenlər işləməyə davam edir.",
        updates_release_20260918d_security_item4: "Abunəlik və Sessiyalar: Ləğv edilən abunəlik ödənilmiş dövrün sonunadək aktiv qalır və 'cihazı ləğv et' əməliyyatı indi bütün səhifələrdə dərhal qüvvəyə minir.",
