        updates_release_20260918_analytics_desc: "İstatistik sayfası sıkışık ve göz yoran grafiklerden arındırılarak Linear ve Vercel standartlarında ferah, sakin ve lüks bir Enterprise yönetim merkezine dönüştürüldü.",
