        updates_release_account_tabs_desc: "/account sayfası Linear ve Vercel tarzında 4 akıcı sekme sistemine geçirildi. Şifre ve e-posta değiştirme formları yan yana tek bir kartta birleştirildi.",
        updates_release_account_tabs_item1: "4-Sekmeli Mimari: Genel & Giriş, Güvenlik (2FA + Oturumlar), Plan & Abonelik ve Geliştirici (Alan Adları + API + Webhooklar) bölümleri ayrıldı.",
        updates_release_account_tabs_item2: "Birleşik Giriş Merkezi: Daha önce sayfanın farklı yerlerinde olan şifre ve e-posta değiştirme formları yan yana tek bir kartta toplandı.",
        updates_release_account_tabs_item3: "Monolith Hissiyatı: Kayan sekme göstergesi, kartların sıralı giriş animasyonları ve mobil uyumlu yatay kaydırma.",
        updates_api_hardening_title: "API ve Webhook güvenlik sertleştirmesi",
        updates_api_hardening_badge: "15.03.2026",
        updates_api_hardening_desc: "API ve webhook akışları daha sıkı güvenlik kuralları ve daha stabil istek yönetimi ile güçlendirildi.",
        updates_api_hardening_item1: "Webhook URL'leri için HTTPS zorunluluğu sertleştirildi (gerektiğinde yalnızca ortam değişkeni ile HTTP açılabilir).",
        updates_api_hardening_item2: "Pro API anahtarlarına scope izinleri eklendi (hesap okuma, link oluşturma, webhook okuma/yazma).",
        updates_api_hardening_item3: "POST /api/pro/v1/shorten endpointine Idempotency-Key desteği eklendi; tekrar eden isteklerde aynı yanıt döner.",
        updates_api_hardening_item4: "Auth ve şifre akışlarındaki sync bcrypt çağrıları async modele taşındı, event-loop bloklanması azaltıldı.",
        updates_api_hardening_item5: "Rate limit anahtarları IP/API key/session tabanlı sertleştirildi ve temel bağımlılıklarda güvenlik güncellemeleri uygulandı.",
        updates_stats_google_fix_title: "İstatistik ve Google giriş kararlılığı düzeltmesi",
        updates_stats_google_fix_badge: "14.03.2026",
        updates_stats_google_fix_desc: "İstatistik API uyumluluğu ve Google OAuth callback akışı daha güvenilir çalışacak şekilde güçlendirildi.",
