        updates_release_20260820_safety_badge: "20.08.2026",
        updates_release_20260820_safety_desc: "0ms kullanıcı gecikmesi ile asenkron güvenlik analizi, zararlı linklerin karantinaya alınması ve haftalık arka plan taraması uygulandı.",
        updates_release_20260820_safety_item1: "0ms Gecikme: Link anında oluşturulur, güvenlik ve oltalama analizi arka planda asenkron çalışır.",
        updates_release_20260820_safety_item2: "Düzenleme Taraması: Kısa linkin hedef adresi güncellendiğinde yeni URL anında güvenlik filtresinden geçer.",
        updates_release_20260820_safety_item3: "Karantina & Bildirim: Zararlı linkler otomatik karantinaya alınır ve kullanıcıya bildirim merkezi ile uyarı gönderilir.",
        updates_release_20260820_safety_item4: "7 Günlük Periyodik Tarama: Tüm aktif linkler haftada bir kez gece saatlerinde sisteme yük bindirmeden taranır.",
        updates_release_20260818_sso_title: "Kurumsal SSO Güvenlik Hardening ve Domain Discovery",
        updates_release_20260818_sso_badge: "18.08.2026",
        updates_release_20260818_sso_desc: "Kurumsal SAML 2.0 SSO sistemi en yüksek güvenlik standartları ve gelişmiş giriş arayüzü ile güncellendi.",
        updates_release_20260818_sso_item1: "Giriş sayfasında otomatik kurumsal alan adı algılama (Domain Discovery) ve 'SSO ile Giriş' seçeneği.",
        updates_release_20260818_sso_item2: "Anti-Replay Attack koruması (Assertion ID önbellekleme) ve HMAC-SHA256 imzalı RelayState güvenliği.",
        updates_release_20260818_sso_item3: "Kriptografik SHA-256 zorunluluğu, saat toleransı (±3 dakika) ve Session Fixation önleme.",
