        updates_release_20260818_adv_badge: "18.08.2026",
        updates_release_20260818_adv_desc: "Gelişmiş link ayarları, UTM şablonları ve PRO özellikleri için kapsamlı güncelleme yayınlandı.",
        updates_release_20260818_adv_item1: "Popüler UTM şablonları (Google Ads, Meta, TikTok, E-posta vb.) ve özel şablon kaydetme.",
        updates_release_20260818_adv_item2: "Gelişmiş ayarlar sekmeleri ve tüm alanlar için eksiksiz 3 dilli (AZ, TR, EN) arayüz desteği.",
