        lang_toggle: "AZ",
        privacy_title: "Privacy Policy",
        privacy_data_collection_title: "Information we collect",
        privacy_data_collection_text: "When you use Ovlink, we process: account data (email, password hash, auth provider, account/sign-in timestamps), link data (destination URL, short code, alias, expiry, click limit, selected domain, hashed link password), click statistics (time, full IP address, browser, operating system, country, city), security/session records (session token, user-agent, device label, country, device fingerprint, IP hash), Pro metadata for API keys (name, prefix, last4, usage time), webhook configurations (URL, event set, active state, failure counters), webhook delivery logs (status, attempts, HTTP code, retry schedule), and report/moderation data.",
        privacy_account_title: "Account information",
        privacy_account_text: "Passwords are never stored in plain text; only hashed values are stored. Email verification, password-reset tokens, and session management are used to protect account access.",
        privacy_analytics_title: "Analytics and security",
        privacy_analytics_text: "Data is processed for service functionality, statistics, abuse reduction, and security. In redirect-consent flow, choosing 'essential' stores only minimal click logging, while choosing 'analytics' stores browser/OS/country statistics. If the visitor does not continue, redirect and click logging do not proceed.",
        privacy_ip_handling_title: "IP data handling",
        privacy_ip_handling_text: "IP/network data is processed during requests for geolocation and security checks. Full IP is not shown in new-device emails, and device sessions store an IP hash instead of full IP. However, full IP addresses and city data are stored in click logs for security and analytics purposes.",
        privacy_moderation_title: "Reports and moderation",
        privacy_moderation_text: "Users can report links. For safety, links may be disabled, domains blocked, and accounts restricted.",
        privacy_retention_title: "Data retention",
        privacy_retention_text: "Data is retained for as long as necessary for service operation, security, legal obligations, and dispute handling. Security-event logs are retained for 30 days by default and automatically purged afterward.",
        privacy_cookies_title: "Cookies",
        privacy_cookies_text: "The site uses connect.sid (session), ovlink_redirect_consent (redirect consent), and lang_default (language preference) cookies. localStorage may store theme, language, and cookie-banner preference (cookieConsent). If ads are enabled, third-party cookie/identifier technologies may run inside ad iframes.",
        privacy_disclaimer_title: "Security notice",
        privacy_disclaimer_text: "We apply security measures, but cannot guarantee 100% security on the internet.",
        privacy_third_party_title: "Third parties",
        privacy_third_party_text: "We use third-party services such as Resend (email), Google OAuth (for registration), Telegram (bot integration), CDN libraries, and infrastructure partners. Your Telegram ID is mapped to your user ID when you connect the bot. These parties process data under their own policies.",
        cookie_more_info: "Learn more",
        privacy_policy: "Privacy Policy",
        maintenance_title: "Maintenance",
        maintenance_msg: "The site is temporarily being updated. We'll be back soon.",
        maintenance_info: "Info",
        terms_title: "Terms of Use",
        terms_intro_title: "General terms",
        terms_intro_text: "Ovlink provides URL shortening, redirect, and link-management services. By using the service, you agree to these Terms, the Privacy Policy, and the Cookie Policy.",
        terms_use_title: "Usage rules",
        terms_use_text: "The service must be used only for lawful and legitimate purposes. Phishing, malware delivery, fraud, spam, deceptive redirects, and illegal content are prohibited.",
        terms_limits_title: "Account Limits",
        terms_limits_text: "Guest (unregistered) users can create a maximum of 5 links per day. The Free plan allows 50 links per day and 1,000 total links; the Pro plan allows 500 links per day and 50,000 total links. Advanced features like API and webhooks are restricted to the Pro plan to protect system resources.",
        terms_content_title: "Content responsibility",
        terms_content_text: "You are responsible for the links you create, the legality of destination content, and your right to share it. Links that violate rules or are considered risky may be restricted, disabled, or removed under policy enforcement.",
        terms_suspension_title: "Restriction and suspension",
        terms_suspension_text: "In cases of abuse, security risk, or legal requirement, links and accounts may be temporarily or permanently restricted, disabled, or removed.",
        terms_limit_title: "Limitation of liability",
        terms_limit_text: "The service is provided as-is. We do not guarantee uninterrupted availability or fitness for a specific purpose, and liability for indirect or consequential losses is limited to the extent permitted by law.",
        terms_privacy_title: "Privacy and data handling",
        terms_privacy_text: "Account, link, session, and click-statistics data are processed for functionality, security, moderation, and support. API key and webhook capabilities are available only while Pro is active; Free and inactive-Pro states are blocked from these features. If ads are enabled, ad-vendor cookie/identifier usage is disclosed in the Privacy and Cookie policies.",
