        cookie_use_text: "Cookies are used for: (1) Essential — connect.sid, redirect consent and security tokens; (2) Functional — language, theme, and workspace preferences; (3) Advertising/Measurement — third-party metrics when ads are active. Pro API keys do not rely on cookies; authentication is strictly header-based.",
