        faq_page_title: "Frequently Asked Questions",
        faq_page_intro: "Common questions and concise answers about using Ovlink.",
        faq_q1: "What is Ovlink?",
        faq_a1: "Ovlink is a URL shortener for creating, sharing, and managing short links.",
        faq_q2: "Is Ovlink free to use?",
        faq_a2: "Core shortening features are available for standard usage. Fair-use and service terms apply.",
        faq_q3: "What is a shortened link?",
        faq_a3: "A shortened link is a compact URL that redirects to a longer destination URL.",
        faq_q4: "How do I create a short link?",
        faq_a4: "Paste a destination URL on the homepage and generate with optional settings.",
        faq_q5: "Can I set a custom alias?",
        faq_a5: "Yes, if available you can assign a custom alias when creating a link.",
        faq_q6: "Can I protect links with a password?",
        faq_a6: "Yes. Password-protected links require verification before redirect.",
        faq_q7: "Can links expire or stop after a click limit?",
        faq_a7: "Yes. You can set expiration and max-click options during link creation.",
        faq_q8: "What happens when someone clicks my short link?",
        faq_a8: "The visitor passes policy and safety checks first, then redirects if allowed.",
        faq_q9: "Can harmful links be removed?",
        faq_a9: "Yes. Reported links may be reviewed and restricted or disabled for safety.",
        faq_q10: "What data is processed?",
        faq_a10: "The service may process submitted link/account data and technical metadata required for operation.",
        faq_q11: "Are cookies used?",
        faq_a11: "Yes. Essential cookies support session and security behavior.",
        faq_q12: "Why might a link not open?",
        faq_a12: "It may be expired, click-limited, moderated, destination-unavailable, or policy-restricted.",
        faq_q13: "How can I report abuse?",
        faq_a13: "Use the report flow on the site and provide the short link plus reason.",
        faq_q14: "How can I contact support?",
        faq_a14: "Use support details listed on the /contact page.",
