// Varsayılan dil (localStorage > cookie > browser > AZ)
function getCookieLang() {
    if (typeof document === "undefined" || !document.cookie) return '';
    const getVal = (name) => {
        const m = document.cookie.match(new RegExp('(?:^|;\\s*)' + name + '=([^;]+)'));
        return m ? decodeURIComponent(m[1]).trim().toLowerCase() : '';
    };
    const valid = ['az', 'tr', 'en'];
    const d = getVal('lang_default');
    if (valid.includes(d)) return d;
    const o = getVal('ovlink_lang');
    if (valid.includes(o)) return o;
    const l = getVal('lang');
    if (valid.includes(l)) return l;
    return '';
}

const storedLang = typeof localStorage !== "undefined" ? (localStorage.getItem("lang") || localStorage.getItem("ovlink_lang")) : null;
const cookieLang = getCookieLang();
const isValidLang = (v) => v === "az" || v === "tr" || v === "en";

function detectBrowserLang() {
    const navLangs = (typeof navigator !== "undefined" && (navigator.languages || [navigator.language || ""])) || [];
    for (const l of navLangs) {
        if (!l) continue;
        const prefix = l.toLowerCase().slice(0, 2);
        if (isValidLang(prefix)) return prefix;
    }
    return "az";
}

let currentLang = isValidLang(storedLang) ? storedLang : (isValidLang(cookieLang) ? cookieLang : detectBrowserLang());

// Immediately persist resolved language across localStorage and cookie so all pages stay in sync
try {
    if (typeof localStorage !== "undefined") {
        localStorage.setItem("lang", currentLang);
        localStorage.setItem("ovlink_lang", currentLang);
    }
    if (typeof document !== "undefined") {
        document.cookie = 'lang_default=' + encodeURIComponent(currentLang) + '; path=/; max-age=31536000; SameSite=Lax';
        document.cookie = 'ovlink_lang=' + encodeURIComponent(currentLang) + '; path=/; max-age=31536000; SameSite=Lax';
        document.cookie = 'lang=' + encodeURIComponent(currentLang) + '; path=/; max-age=31536000; SameSite=Lax';
    }
} catch(_) {}

function getCurrentLanguage() {
    return currentLang;
}

function applyLanguage() {
    if (typeof document === "undefined") return;
    const elements = document.querySelectorAll("[data-i18n]");
    elements.forEach(el => {
        const key = el.getAttribute("data-i18n");
        if (translations[currentLang] && translations[currentLang][key]) {
            if (el.tagName === "INPUT" || el.tagName === "TEXTAREA") {
                el.placeholder = translations[currentLang][key];
            } else {
                el.textContent = translations[currentLang][key];
            }
        }
    });

    const placeholders = document.querySelectorAll("[data-i18n-placeholder]");
    placeholders.forEach(el => {
        const key = el.getAttribute("data-i18n-placeholder");
        if (translations[currentLang] && translations[currentLang][key]) {
            el.placeholder = translations[currentLang][key];
            el.setAttribute("placeholder", translations[currentLang][key]);
        }
    });

    const titles = document.querySelectorAll("[data-i18n-title]");
    titles.forEach(el => {
        const key = el.getAttribute("data-i18n-title");
        if (translations[currentLang] && translations[currentLang][key]) {
            el.title = translations[currentLang][key];
            el.setAttribute("data-bs-original-title", translations[currentLang][key]);
        }
    });

    const arias = document.querySelectorAll("[data-i18n-aria]");
    arias.forEach(el => {
        const key = el.getAttribute("data-i18n-aria");
        if (translations[currentLang] && translations[currentLang][key]) {
            el.setAttribute("aria-label", translations[currentLang][key]);
        }
    });

    const getEl = (id) => (typeof document !== "undefined" && typeof document.getElementById === "function" ? document.getElementById(id) : null);
    const banner = getEl("siteAnnouncement");
    const bannerText = getEl("siteAnnouncementText");
    if (banner && bannerText) {
        const az = banner.getAttribute("data-az") || "";
        const tr = banner.getAttribute("data-tr") || "";
        const en = banner.getAttribute("data-en") || "";
        const textValue = currentLang === "tr" ? (tr || az || en) : (currentLang === "en" ? (en || az || tr) : (az || tr || en));
        bannerText.textContent = textValue;
        if (!textValue) {
            banner.classList.add("d-none");
        } else {
            banner.classList.remove("d-none");
        }
    }

    if (typeof window !== "undefined" && typeof window.applyNotificationLanguage === 'function') {
        window.applyNotificationLanguage();
    }
    if (typeof window !== "undefined" && typeof window.refreshCustomDomainUi === 'function') {
        window.refreshCustomDomainUi();
    }
    if (typeof window !== "undefined" && typeof window.loadUtmTemplatesUi === 'function') {
        window.loadUtmTemplatesUi();
    }

    const toggleBtn = getEl("langToggleBtn");
    if (toggleBtn) {
        toggleBtn.textContent = currentLang.toUpperCase();
    }
    const toggleBtnMobile = getEl("langToggleBtnMobile");
    if (toggleBtnMobile) {
        toggleBtnMobile.textContent = currentLang.toUpperCase();
    }

    const langOptions = typeof document !== "undefined" && typeof document.querySelectorAll === "function" 
        ? document.querySelectorAll(".lang-option, .m-lang-item") 
        : [];
    if (langOptions.length) {
        langOptions.forEach(option => {
            const optionLang = option.getAttribute("data-lang");
            const labelKey = optionLang === "az" ? "lang_az" : (optionLang === "tr" ? "lang_tr" : "lang_en");
            if (translations[currentLang] && translations[currentLang][labelKey]) {
                option.textContent = translations[currentLang][labelKey];
            } else if (optionLang) {
                option.textContent = optionLang.toUpperCase();
            }
            const isActive = optionLang === currentLang;
            option.classList.toggle("active", isActive);
            option.classList.toggle("is-active", isActive);
            if (isActive) {
                option.setAttribute("aria-current", "true");
            } else {
                option.removeAttribute("aria-current");
            }
        });
    }

    // HTML lang attribute güncelle
    if (typeof document !== "undefined" && document.documentElement) {
        document.documentElement.lang = currentLang;
    }
}

function setLanguage(lang) {
    if (!isValidLang(lang)) return;
    currentLang = lang;
    try {
        if (typeof localStorage !== "undefined") {
            localStorage.setItem("lang", currentLang);
            localStorage.setItem("ovlink_lang", currentLang);
        }
        if (typeof document !== "undefined") {
            document.cookie = 'lang_default=' + encodeURIComponent(currentLang) + '; path=/; max-age=31536000; SameSite=Lax';
            document.cookie = 'ovlink_lang=' + encodeURIComponent(currentLang) + '; path=/; max-age=31536000; SameSite=Lax';
            document.cookie = 'lang=' + encodeURIComponent(currentLang) + '; path=/; max-age=31536000; SameSite=Lax';
        }
    } catch {}
    applyLanguage();
    if (typeof window !== "undefined" && typeof window.dispatchEvent === "function") {
        window.dispatchEvent(new CustomEvent("ovlink:languageChanged", { detail: { lang: currentLang } }));
    }
    // Background sync to server so user account in DB updates immediately
    try {
        if (typeof fetch === "function") {
            const metaCsrf = document.querySelector('meta[name="csrf-token"]');
            const csrfToken = metaCsrf ? metaCsrf.getAttribute('content') : '';
            fetch('/api/user/ui-lang', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    'CSRF-Token': csrfToken,
                    'x-csrf-token': csrfToken
                },
                body: JSON.stringify({ lang: currentLang, _csrf: csrfToken })
            }).catch(() => {});
        }
    } catch (_) {}
}

function toggleLanguage() {
    const nextLang = currentLang === "az" ? "tr" : (currentLang === "tr" ? "en" : "az");
    setLanguage(nextLang);
}

function initLangUi() {
    applyLanguage();

    const langOptions = typeof document !== "undefined" && typeof document.querySelectorAll === "function" 
        ? document.querySelectorAll(".lang-option, .m-lang-item") 
        : [];
    if (langOptions.length) {
        langOptions.forEach(option => {
            option.addEventListener("click", (e) => {
                e.preventDefault();
                const selected = option.getAttribute("data-lang");
                if (selected) {
                    setLanguage(selected);
                }
                if (typeof document !== "undefined" && typeof document.querySelectorAll === "function") {
                    document.querySelectorAll(".m-lang-panel, .lang-menu").forEach(p => p.classList.remove("open", "is-open"));
                    document.querySelectorAll(".m-lang-btn, [data-lang-btn]").forEach(b => b.setAttribute("aria-expanded", "false"));
                }
            });
        });
        return;
    }

    const getEl = (id) => (typeof document !== "undefined" && typeof document.getElementById === "function" ? document.getElementById(id) : null);
    const toggleBtn = getEl("langToggleBtn");
    if (toggleBtn) {
        toggleBtn.addEventListener("click", (e) => {
            e.preventDefault();
            toggleLanguage();
        });
    }
}

if (typeof document !== "undefined") {
    if (document.readyState === "loading") {
        window.addEventListener("DOMContentLoaded", initLangUi);
    } else {
        initLangUi();
    }
}

if (typeof module !== "undefined" && module.exports) {
    module.exports = { translations, setLanguage, getCurrentLanguage };
}



